handler_code = '''"""
Thin CLI wrapper around the retail-domain tools.
"""
from __future__ import annotations
import json, sys, pathlib, importlib, inspect

_src = pathlib.Path(__file__).resolve().parent.parent  # .../src
if str(_src) not in sys.path:
    sys.path.insert(0, str(_src))

from tau2.domains.retail import tools as _tools

def _public_tools() -> dict:
    return {
        name: obj
        for name, obj in inspect.getmembers(_tools, inspect.isfunction)
        if not name.startswith("_")
    }

def _parse_cli():
    args = sys.argv[1:]
    if not args:
        print(json.dumps({"ok": False, "error": "usage: tool_handler.py <tool> [--json '{...}' | --k v]"}))
        sys.exit(1)
    tool_name = args[0]
    if tool_name == "list":
        return ("list", {})
    rest = args[1:]
    if len(rest) >= 2 and rest[0] == "--json":
        return (tool_name, json.loads(rest[1]))
    kv = {}
    i = 0
    while i < len(rest):
        key = rest[i].lstrip("-")
        if i + 1 < len(rest) and not rest[i + 1].startswith("--"):
            val = rest[i + 1]
            if val.lower() in ("true", "false"):
                val = val.lower() == "true"
            else:
                try:
                    val = int(val)
                except ValueError:
                    try:
                        val = float(val)
                    except ValueError:
                        pass
            kv[key] = val
            i += 2
        else:
            kv[key] = True
            i += 1
    return (tool_name, kv)

def main():
    tool_name, kwargs = _parse_cli()
    tools = _public_tools()
    if tool_name == "list":
        print(json.dumps(sorted(tools.keys()), indent=2))
        return
    if tool_name not in tools:
        print(json.dumps({"ok": False, "error": f"unknown tool: {tool_name}"}))
        sys.exit(1)
    try:
        result = tools[tool_name](**kwargs)
        print(json.dumps({"ok": True, "result": result}, default=str))
    except Exception as exc:
        print(json.dumps({"ok": False, "error": f"{type(exc).__name__}: {exc}"}))

if __name__ == "__main__":
    main()
'''
